import { Univer } from '@univerjs/core';
import { UniverSheetsPlugin } from '@univerjs/sheets';

const univer = new Univer();
univer.registerPlugin(UniverSheetsPlugin);

import { createAgentClient } from '@ag-ui/core';

const client = createAgentClient({ endpoint: 'https://api.agent.io' });
client.on('message', (event) => console.log(event));

const tensorfold = @import("tensorfold");

pub fn main() !void {
    var engine = try tensorfold.Engine.init("path/to/checkpoint");
    defer engine.deinit();
    try engine.generate("Hello, TensorFold!");
}

import { Button } from '@astryxdesign/core';

export function App() {
  return <Button variant="primary">Hello Astryx</Button>;
}

import { runSecurityAudit } from '@cloudflare/security-audit-skill';

await runSecurityAudit({
  targetDir: './src',
  phases: ['recon', 'hunting', 'validation', 'reporting']
});

import { REAProtocol } from 'rea-agents';

const analyzer = new REAProtocol();
await analyzer.inspectBinary('./target-app.bin');

import { T3CodeServer } from 't3code';

const server = new T3CodeServer({ port: 3000 });
await server.start();

import { ClaudeMem } from 'claude-mem';

const memory = new ClaudeMem();
await memory.injectContext({ sessionKey: 'current-workspace' });

import { HyperFrame } from 'hyperframes';

const frame = new HyperFrame();
await frame.render('<h1>Hello Video</h1>');

// 에이전트 설정에 Taste Skill 통합
import { registerTasteSkill } from 'taste-skill';
registerTasteSkill({ level: 'pro' });

import { ShotCraft } from 'video-shotcraft';

const video = new ShotCraft({
  recipe: 'cinematic-product-promo',
  beatSync: true,
  exportTarget: 'remotion'
});
await video.render({ output: 'promo.mp4' });
